import React, { createContext, useContext, useState, useEffect, useCallback, useMemo } from 'react';
import { getProfile as fetchProfile } from '../services/api';

const AppContext = createContext();

export function useApp() {
  return useContext(AppContext);
}

export function AppProvider({ children }) {
  // Mobile Sidebar State
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Auth token
  const [authToken, setAuthToken] = useState(() => localStorage.getItem('moodcare-token') || null);
  const isAuthenticated = !!authToken;

  // User Profile State
  const [userProfile, setUserProfile] = useState(() => {
    try {
      const saved = localStorage.getItem('moodcare-userProfile');
      return saved ? JSON.parse(saved) : {
        name: 'User',
        email: '',
        phone: '',
        avatar: "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 128 128'%3E%3Ccircle cx='64' cy='64' r='64' fill='%23e2e8f0'/%3E%3Ccircle cx='64' cy='50' r='22' fill='%2394a3b8'/%3E%3Cellipse cx='64' cy='106' rx='38' ry='28' fill='%2394a3b8'/%3E%3C/svg%3E",
        preferredTone: 'friendly',
        reminderTime: '09:00',
        anonymousMode: false
      };
    } catch {
      return {
        name: 'User',
        email: '',
        phone: '',
        avatar: "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 128 128'%3E%3Ccircle cx='64' cy='64' r='64' fill='%23e2e8f0'/%3E%3Ccircle cx='64' cy='50' r='22' fill='%2394a3b8'/%3E%3Cellipse cx='64' cy='106' rx='38' ry='28' fill='%2394a3b8'/%3E%3C/svg%3E",
        preferredTone: 'friendly',
        reminderTime: '09:00',
        anonymousMode: false
      };
    }
  });

  const [darkMode, setDarkMode] = useState(() => {
    const saved = localStorage.getItem('moodcare-darkMode');
    return saved === 'true';
  });

  const [language, setLanguage] = useState(() => {
    return localStorage.getItem('moodcare-language') || 'en';
  });

  const [currentMood, setCurrentMood] = useState(() => {
    return localStorage.getItem('moodcare-currentMood') || 'calm';
  });

  const [stressLevel, setStressLevel] = useState(() => {
    const saved = localStorage.getItem('moodcare-stressLevel');
    return saved ? parseInt(saved, 10) : 20;
  });

  const [aiMemory, setAiMemory] = useState(() => {
    try {
      const saved = localStorage.getItem('moodcare-aiMemory');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const addMemory = useCallback((entry) => {
    setAiMemory(prev => {
      const updated = [...prev, { ...entry, timestamp: Date.now() }].slice(-10);
      return updated;
    });
  }, []);

  // ── Auth functions (memoized to prevent child re-renders) ───
  const login = useCallback((token, user) => {
    localStorage.setItem('moodcare-token', token);
    setAuthToken(token);
    setUserProfile(prev => ({
      ...prev,
      name: user.name,
      email: user.email,
      phone: user.phone || '',
      preferredTone: user.preferred_tone || 'friendly',
      reminderTime: user.reminder_time || '09:00',
      anonymousMode: user.anonymous_mode || false,
      avatar: user.avatar_url || prev.avatar,
    }));
  }, []);

  const logout = useCallback(() => {
    localStorage.removeItem('moodcare-token');
    setAuthToken(null);
    setUserProfile({
      name: 'User',
      email: '',
      phone: '',
      avatar: "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 128 128'%3E%3Ccircle cx='64' cy='64' r='64' fill='%23e2e8f0'/%3E%3Ccircle cx='64' cy='50' r='22' fill='%2394a3b8'/%3E%3Cellipse cx='64' cy='106' rx='38' ry='28' fill='%2394a3b8'/%3E%3C/svg%3E",
      preferredTone: 'friendly',
      reminderTime: '09:00',
      anonymousMode: false,
    });
  }, []);

  // ── Fetch profile on app load if token exists ───────────────
  useEffect(() => {
    if (authToken) {
      fetchProfile()
        .then(res => {
          const user = res.data;
          setUserProfile(prev => ({
            ...prev,
            name: user.name,
            email: user.email,
            phone: user.phone || '',
            preferredTone: user.preferred_tone || 'friendly',
            reminderTime: user.reminder_time || '09:00',
            anonymousMode: user.anonymous_mode || false,
            avatar: user.avatar_url || prev.avatar,
          }));
        })
        .catch((err) => {
          // Only logout if it's a 401 — other errors should not force logout
          if (err.response?.status === 401) {
            logout();
          }
        });
    }
  }, [authToken, logout]);

  // ── Consolidated localStorage persistence ───────────────────
  useEffect(() => {
    localStorage.setItem('moodcare-userProfile', JSON.stringify(userProfile));
  }, [userProfile]);

  useEffect(() => {
    localStorage.setItem('moodcare-darkMode', darkMode);
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  useEffect(() => {
    localStorage.setItem('moodcare-language', language);
    document.documentElement.setAttribute('dir', language === 'ur' ? 'rtl' : 'ltr');
    document.documentElement.setAttribute('lang', language);
  }, [language]);

  useEffect(() => {
    localStorage.setItem('moodcare-currentMood', currentMood);
    document.documentElement.setAttribute('data-mood', currentMood);
  }, [currentMood]);

  useEffect(() => {
    localStorage.setItem('moodcare-stressLevel', stressLevel);
  }, [stressLevel]);

  useEffect(() => {
    localStorage.setItem('moodcare-aiMemory', JSON.stringify(aiMemory));
  }, [aiMemory]);

  const toggleDarkMode = useCallback(() => setDarkMode(prev => !prev), []);

  const updateProfile = useCallback((key, value) => {
    setUserProfile(prev => ({ ...prev, [key]: value }));
  }, []);

  // ── Memoize context value to prevent unnecessary re-renders ─
  const contextValue = useMemo(() => ({
    darkMode, toggleDarkMode,
    language, setLanguage,
    currentMood, setCurrentMood,
    stressLevel, setStressLevel,
    aiMemory, addMemory,
    userProfile, setUserProfile, updateProfile,
    isSidebarOpen, setIsSidebarOpen,
    // Auth
    authToken, isAuthenticated, login, logout,
  }), [
    darkMode, toggleDarkMode,
    language, setLanguage,
    currentMood, setCurrentMood,
    stressLevel, setStressLevel,
    aiMemory, addMemory,
    userProfile, setUserProfile, updateProfile,
    isSidebarOpen, setIsSidebarOpen,
    authToken, isAuthenticated, login, logout,
  ]);

  return (
    <AppContext.Provider value={contextValue}>
      {children}
    </AppContext.Provider>
  );
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Send, Mic, Square, AlertTriangle, Phone, Heart, Shield } from 'lucide-react';
import { useApp } from '../context/AppContext';
import { t } from '../translations';
import { sendChatMessage, getChatHistory } from '../services/api';

// Emotion configs
const emotions = {
  happy:   { emoji: '😄', color: 'bg-emerald-50 text-emerald-600 border-emerald-100', dotColor: 'bg-emerald-500', darkColor: 'bg-emerald-900/30 text-emerald-400 border-emerald-800/50' },
  anxious: { emoji: '😟', color: 'bg-amber-50 text-amber-600 border-amber-100', dotColor: 'bg-amber-500', darkColor: 'bg-amber-900/30 text-amber-400 border-amber-800/50' },
  sad:     { emoji: '😞', color: 'bg-blue-50 text-blue-600 border-blue-100', dotColor: 'bg-blue-500', darkColor: 'bg-blue-900/30 text-blue-400 border-blue-800/50' },
  calm:    { emoji: '😌', color: 'bg-emerald-50 text-emerald-600 border-emerald-100', dotColor: 'bg-emerald-500', darkColor: 'bg-emerald-900/30 text-emerald-400 border-emerald-800/50' },
  stressed:{ emoji: '😰', color: 'bg-red-50 text-red-600 border-red-100', dotColor: 'bg-red-500', darkColor: 'bg-red-900/30 text-red-400 border-red-800/50' },
};

function detectEmotion(text) {
  const lower = text.toLowerCase();
  if (/stress|overwhelm|pressure|tense|burden|تناؤ|دباؤ|بوجھ/.test(lower)) return 'stressed';
  if (/sad|depress|cry|lonely|down|hurt|اداس|تنہا|رونا/.test(lower)) return 'sad';
  if (/anxi|worry|nervous|scared|fear|panic|فکر|خوف|گھبراہٹ/.test(lower)) return 'anxious';
  if (/happy|great|amazing|wonderful|joy|excited|good|خوش|بہترین|خوشی/.test(lower)) return 'happy';
  if (/آرام|سکون|relax/.test(lower)) return 'calm';
  return 'calm';
}

function detectCrisis(text) {
  const lower = text.toLowerCase();
  return /suicid|kill myself|end it all|don't want to live|self.?harm|خودکشی|مرنا/.test(lower);
}

function formatTime(date) {
  return new Date(date).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}

export default function Chat() {
  const [isRecording, setIsRecording] = useState(false);
  const [showCrisisAlert, setShowCrisisAlert] = useState(false);
  const [inputValue, setInputValue] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [currentEmotion, setCurrentEmotion] = useState('calm');
  const [messages, setMessages] = useState([]);
  const [loadingHistory, setLoadingHistory] = useState(true);
  const { darkMode, language, currentMood, setCurrentMood, addMemory, userProfile } = useApp();
  const messagesEndRef = useRef(null);
  const historyLoadedRef = useRef(false);

  const firstName = userProfile?.name?.split(' ')[0] || 'User';

  // Load chat history from backend on mount
  useEffect(() => {
    getChatHistory()
      .then(res => {
        const history = res.data.map(msg => ({
          id: msg.id,
          sender: msg.sender,
          text: msg.message,
          time: msg.created_at,
          emotion: msg.emotion,
        }));
        setMessages(history);

        // Set current emotion from last user message
        const lastUser = [...history].reverse().find(m => m.sender === 'user');
        if (lastUser && lastUser.emotion) {
          setCurrentEmotion(lastUser.emotion);
        }
      })
      .catch(() => {
        // If no history, start with a welcome message (local only)
        setMessages([{
          id: 'welcome',
          sender: 'ai',
          text: `Hi ${firstName}! 👋 I'm your MoodCare AI companion. How are you feeling today?`,
          time: new Date().toISOString(),
        }]);
      })
      .finally(() => {
        setLoadingHistory(false);
        historyLoadedRef.current = true;
      });
  }, []);

  // Auto-scroll
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isTyping]);

  // Detect emotion from messages — only for new messages, not history load
  useEffect(() => {
    if (!historyLoadedRef.current) return; // Skip during initial history load
    const lastUserMsg = [...messages].reverse().find(m => m.sender === 'user');
    if (lastUserMsg) {
      const emotion = lastUserMsg.emotion || detectEmotion(lastUserMsg.text);
      setCurrentEmotion(emotion);
      setCurrentMood(emotion);
      if (detectCrisis(lastUserMsg.text)) {
        setShowCrisisAlert(true);
      }
    }
  }, [messages]);

  const handleSendMessage = async (text) => {
    if (!text.trim()) return;

    const userMsg = { id: Date.now(), sender: 'user', text: text.trim(), time: new Date().toISOString() };
    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setIsTyping(true);

    // Add to local memory
    const emotion = detectEmotion(text);
    addMemory({ text: text.trim().slice(0, 50), mood: emotion });

    try {
      const res = await sendChatMessage(text.trim());
      const aiData = res.data.ai_message;
      setMessages(prev => [...prev, {
        id: aiData.id,
        sender: 'ai',
        text: aiData.message,
        time: aiData.created_at,
        emotion: aiData.emotion,
      }]);
    } catch {
      // Fallback if API fails
      setMessages(prev => [...prev, {
        id: Date.now() + 1,
        sender: 'ai',
        text: "I'm having trouble connecting right now. Please try again in a moment. 💙",
        time: new Date().toISOString(),
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage(inputValue);
    }
  };

  const em = emotions[currentEmotion] || emotions.calm;

  const chips = [
    { key: 'chipStressed', fallback: 'I feel stressed' },
    { key: 'chipAdvice', fallback: 'Give me advice' },
    { key: 'chipRelax', fallback: 'Help me relax' },
    { key: 'chipAnxious', fallback: 'I feel anxious' },
  ];

  return (
    <div className="flex flex-col h-[calc(100vh-5rem)] md:h-[calc(100vh-6rem)] animate-fade-in">
      <header className="mb-3 md:mb-4 flex flex-col sm:flex-row sm:justify-between sm:items-center gap-2">
        <div>
          <h1 className={`text-2xl sm:text-3xl font-bold tracking-tight ${darkMode ? 'text-slate-100' : 'text-slate-800'}`}>{t('aiTherapist', language)}</h1>
          <p className={`mt-0.5 text-sm sm:text-base ${darkMode ? 'text-slate-400' : 'text-slate-500'}`}>{t('yourSafeSpace', language)}</p>
        </div>
        <div className={`${darkMode ? em.darkColor : em.color} px-3 sm:px-4 py-1 sm:py-1.5 rounded-full text-xs sm:text-sm font-bold border shadow-sm flex items-center gap-2 transition-all duration-500 w-fit`}>
          <span className={`w-2 h-2 rounded-full ${em.dotColor} animate-pulse`}></span>
          <span>{em.emoji}</span>
          {t(currentEmotion, language)}
        </div>
      </header>

      {showCrisisAlert && (
        <div className={`mb-3 md:mb-4 p-4 sm:p-5 rounded-3xl shadow-lg flex items-start sm:items-center justify-between flex-col sm:flex-row gap-3 sm:gap-4 animate-scale-in border ${
          darkMode
            ? 'bg-gradient-to-r from-red-900/40 to-pink-900/30 border-red-800/50'
            : 'bg-gradient-to-r from-red-50 to-pink-50 border-red-100'
        }`}>
          <div className="flex items-start gap-3 sm:gap-4">
            <div className={`p-2.5 sm:p-3 rounded-2xl flex-shrink-0 ${darkMode ? 'bg-red-900/50' : 'bg-red-100'}`}>
              <Heart className={`${darkMode ? 'text-red-400' : 'text-red-500'} fill-current`} size={22} />
            </div>
            <div>
              <p className={`font-bold text-sm sm:text-base mb-1 ${darkMode ? 'text-red-300' : 'text-red-800'}`}>
                {t('crisisDetected', language)}
              </p>
              <p className={`text-xs sm:text-sm leading-relaxed ${darkMode ? 'text-slate-300' : 'text-red-700'}`}>
                {t('crisisMessage', language)}
              </p>
            </div>
          </div>
          <div className="flex gap-2 w-full sm:w-auto">
            <button 
              onClick={() => setShowCrisisAlert(false)}
              className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-gradient-to-r from-red-500 to-pink-500 hover:from-red-600 hover:to-pink-600 text-white px-4 sm:px-5 py-2.5 rounded-2xl text-sm font-bold transition-all shadow-md hover:shadow-lg whitespace-nowrap"
            >
              <Phone size={16} />
              {t('contactHelpline', language)}
            </button>
            <button 
              onClick={() => setShowCrisisAlert(false)}
              className={`p-2.5 rounded-xl transition-colors ${darkMode ? 'text-slate-400 hover:bg-slate-700' : 'text-slate-400 hover:bg-slate-100'}`}
            >
              <Shield size={16} />
            </button>
          </div>
        </div>
      )}

      <div className={`flex-1 backdrop-blur-xl rounded-2xl sm:rounded-3xl shadow-[0_8px_30px_rgb(0,0,0,0.04)] border flex flex-col overflow-hidden ${
        darkMode 
          ? 'bg-slate-800/60 border-slate-700/50' 
          : 'bg-white/60 border-white/50'
      }`}>
        <div className="flex-1 overflow-y-auto p-3 sm:p-6 space-y-4 sm:space-y-6 bg-transparent">
          {loadingHistory ? (
            <div className="flex items-center justify-center h-full">
              <div className="w-8 h-8 border-3 border-primary-500 border-t-transparent rounded-full animate-spin"></div>
            </div>
          ) : (
            messages.map((msg, idx) => (
              <div key={msg.id} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'} animate-slide-up`} style={{ animationDelay: `${Math.min(idx * 50, 500)}ms` }}>
                <div className="flex flex-col gap-1 max-w-[85%] sm:max-w-xl">
                  <div className={
                    msg.sender === 'user'
                      ? 'bg-gradient-to-r from-primary-600 to-primary-500 text-white px-4 sm:px-6 py-3 sm:py-4 rounded-3xl rounded-tr-sm shadow-md font-medium leading-relaxed text-sm sm:text-base'
                      : `px-4 sm:px-6 py-3 sm:py-4 rounded-3xl rounded-tl-sm border shadow-sm leading-relaxed text-sm sm:text-base ${
                          darkMode 
                            ? 'bg-slate-700/80 text-slate-200 border-slate-600/60' 
                            : 'bg-white/80 backdrop-blur-md text-slate-800 border-white/60'
                        }`
                  }>
                    <p>{msg.text}</p>
                  </div>
                  <span className={`text-[11px] px-2 ${
                    msg.sender === 'user' ? 'text-right' : 'text-left'
                  } ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>
                    {formatTime(msg.time)}
                  </span>
                </div>
              </div>
            ))
          )}

          {isTyping && (
            <div className="flex justify-start animate-fade-in">
              <div className={`px-4 sm:px-6 py-3 sm:py-4 rounded-3xl rounded-tl-sm border shadow-sm ${
                darkMode 
                  ? 'bg-slate-700/80 border-slate-600/60' 
                  : 'bg-white/80 backdrop-blur-md border-white/60'
              }`}>
                <div className="flex items-center gap-2">
                  <div className="flex gap-1">
                    <span className={`w-2 h-2 sm:w-2.5 sm:h-2.5 rounded-full animate-bounce ${darkMode ? 'bg-primary-400' : 'bg-primary-500'}`} style={{ animationDelay: '0ms' }}></span>
                    <span className={`w-2 h-2 sm:w-2.5 sm:h-2.5 rounded-full animate-bounce ${darkMode ? 'bg-primary-400' : 'bg-primary-500'}`} style={{ animationDelay: '150ms' }}></span>
                    <span className={`w-2 h-2 sm:w-2.5 sm:h-2.5 rounded-full animate-bounce ${darkMode ? 'bg-primary-400' : 'bg-primary-500'}`} style={{ animationDelay: '300ms' }}></span>
                  </div>
                  <span className={`text-xs sm:text-sm font-medium ${darkMode ? 'text-slate-400' : 'text-slate-500'}`}>
                    {t('aiIsTyping', language)}
                  </span>
                </div>
              </div>
            </div>
          )}

          <div ref={messagesEndRef} />
        </div>

        <div className={`p-3 sm:p-4 backdrop-blur-md border-t ${
          darkMode 
            ? 'bg-slate-800/40 border-slate-700/40' 
            : 'bg-white/40 border-white/40'
        }`}>
          <div className="flex flex-wrap gap-1.5 sm:gap-2 mb-2 sm:mb-3 px-1">
            {chips.map((chip) => (
              <button
                key={chip.key}
                onClick={() => handleSendMessage(t(chip.key, language))}
                className={`px-3 sm:px-4 py-1.5 sm:py-2 rounded-full text-xs sm:text-sm font-semibold transition-all hover:scale-[1.03] active:scale-95 border shadow-sm hover-glow ${
                  darkMode
                    ? 'bg-slate-700 text-primary-400 border-slate-600 hover:bg-slate-600 hover:text-primary-300'
                    : 'bg-white/80 text-primary-600 border-primary-100 hover:bg-primary-50 hover:border-primary-200'
                }`}
              >
                {t(chip.key, language)}
              </button>
            ))}
          </div>

          <div className={`relative flex items-center rounded-full border px-2 sm:px-3 py-1.5 sm:py-2 focus-within:ring-2 focus-within:ring-primary-100 focus-within:border-primary-400 transition-all shadow-sm group ${
            darkMode 
              ? 'bg-slate-700 border-slate-600' 
              : 'bg-slate-50 border-slate-200'
          }`}>
            <input 
              type="text" 
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder={t('typeYourMessage', language)}
              className={`flex-1 bg-transparent border-none outline-none py-1.5 sm:py-2 px-2 sm:px-4 text-sm sm:text-lg min-w-0 ${
                darkMode ? 'text-slate-200 placeholder:text-slate-500' : 'text-slate-700 placeholder:text-slate-400'
              }`}
            />
            <div className="flex gap-1.5 sm:gap-2 shrink-0">
              <button 
                onClick={() => setIsRecording(!isRecording)}
                className={`p-2 sm:p-3 rounded-full transition-all shadow-sm border ${
                  isRecording 
                    ? 'bg-red-50 text-red-500 border-red-200 hover:bg-red-100 animate-pulse' 
                    : darkMode
                      ? 'bg-slate-600 text-slate-300 border-slate-500 hover:bg-slate-500 hover:text-primary-400'
                      : 'bg-white text-slate-500 border-slate-100 hover:bg-slate-50 hover:text-primary-600'
                }`}
              >
                {isRecording ? <Square size={18} className="fill-current sm:w-[22px] sm:h-[22px]" /> : <Mic size={18} className="stroke-[2.5] sm:w-[22px] sm:h-[22px]" />}
              </button>
              <button 
                onClick={() => handleSendMessage(inputValue)}
                className="p-2 sm:p-3 bg-gradient-to-r from-primary-600 to-primary-500 hover:from-primary-700 hover:to-primary-600 text-white rounded-full transition-all shadow-md hover:shadow-lg hover-glow"
              >
                <Send size={18} className="ml-0.5 stroke-[2.5] sm:w-[22px] sm:h-[22px]" />
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { useNavigate, Navigate } from 'react-router-dom';
import { Smile, Sparkles, LogIn, UserPlus, AlertCircle } from 'lucide-react';
import { useApp } from '../context/AppContext';
import { t } from '../translations';
import { registerUser, loginUser } from '../services/api';

export default function Login() {
  const [isLogin, setIsLogin] = useState(true);
  const [formName, setFormName] = useState('');
  const [formEmail, setFormEmail] = useState('');
  const [formPassword, setFormPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const { darkMode, language, login, isAuthenticated } = useApp();

  // If already logged in, redirect to dashboard
  if (isAuthenticated) {
    return <Navigate to="/dashboard" replace />;
  }

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      let res;
      if (isLogin) {
        res = await loginUser(formEmail, formPassword);
      } else {
        res = await registerUser(formName, formEmail, formPassword);
      }

      const { access_token, user } = res.data;
      login(access_token, user);
      // Redirect happens automatically via <Navigate> on re-render
    } catch (err) {
      const msg = err.response?.data?.detail || 'Something went wrong. Please try again.';
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  const inputClass = `w-full px-5 py-3.5 rounded-2xl border focus:outline-none focus:ring-4 focus:ring-primary-500/20 focus:border-primary-400 transition-all shadow-inner font-medium ${
    darkMode 
      ? 'bg-slate-700/50 border-slate-600 text-slate-200 placeholder:text-slate-500' 
      : 'bg-white/50 border-white/40 text-slate-800 placeholder:text-slate-400'
  }`;

  return (
    <div className={`relative min-h-screen flex items-center justify-center overflow-hidden selection:bg-primary-500 selection:text-white px-4 ${
      darkMode ? 'bg-slate-900' : 'bg-slate-50'
    }`}>
      {/* Dynamic Background Blobs */}
      <div className={`absolute top-[-10%] left-[-10%] w-64 sm:w-96 h-64 sm:h-96 rounded-full mix-blend-multiply filter blur-[80px] animate-pulse ${
        darkMode ? 'bg-primary-500/15 opacity-50' : 'bg-primary-400/30 opacity-70'
      }`}></div>
      <div className={`absolute top-[20%] right-[-10%] w-64 sm:w-96 h-64 sm:h-96 rounded-full mix-blend-multiply filter blur-[80px] animate-pulse ${
        darkMode ? 'bg-purple-500/15 opacity-50' : 'bg-purple-400/30 opacity-70'
      }`} style={{ animationDelay: '2s' }}></div>
      <div className={`absolute bottom-[-10%] left-[20%] w-64 sm:w-96 h-64 sm:h-96 rounded-full mix-blend-multiply filter blur-[80px] animate-pulse ${
        darkMode ? 'bg-accent-teal/10 opacity-40' : 'bg-accent-teal/30 opacity-70'
      }`} style={{ animationDelay: '4s' }}></div>

      <div className={`relative w-full max-w-md p-6 sm:p-8 md:p-10 backdrop-blur-2xl border shadow-[0_8px_32px_0_rgba(31,38,135,0.07)] rounded-[2rem] sm:rounded-[2.5rem] animate-fade-in ${
        darkMode 
          ? 'bg-slate-800/60 border-slate-700/50' 
          : 'bg-white/60 border-white/50'
      }`}>

        <div className="absolute -top-10 sm:-top-12 left-1/2 -translate-x-1/2">
          <div className="bg-gradient-to-br from-primary-500 to-purple-600 p-3 sm:p-4 rounded-2xl sm:rounded-3xl text-white shadow-xl shadow-primary-500/30 border-4 border-white">
            <Sparkles size={28} className="fill-current sm:w-9 sm:h-9" />
          </div>
        </div>

        <div className="mt-4 sm:mt-6 text-center mb-6 sm:mb-8">
          <h2 className={`text-2xl sm:text-3xl font-extrabold mb-2 ${
            darkMode 
              ? 'text-slate-100' 
              : 'text-transparent bg-clip-text bg-gradient-to-r from-slate-800 to-slate-600'
          }`}>
            {isLogin ? t('welcomeBack', language) : t('createAccount', language)}
          </h2>
          <p className={`font-medium text-sm sm:text-base ${darkMode ? 'text-slate-400' : 'text-slate-500'}`}>
            {isLogin ? t('loginSubtitle', language) : t('signupSubtitle', language)}
          </p>
        </div>

        {/* Error Message */}
        {error && (
          <div className={`mb-4 p-3 rounded-xl flex items-center gap-2 text-sm font-medium animate-slide-up ${
            darkMode ? 'bg-red-900/30 text-red-400 border border-red-800/50' : 'bg-red-50 text-red-600 border border-red-100'
          }`}>
            <AlertCircle size={16} className="shrink-0" />
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4 sm:space-y-5">
          <div className={`transition-all duration-500 ease-in-out overflow-hidden ${isLogin ? 'max-h-0 opacity-0' : 'max-h-24 opacity-100'}`}>
            <label className={`block text-sm font-bold mb-1.5 ml-1 ${darkMode ? 'text-slate-300' : 'text-slate-700'}`}>{t('name', language)}</label>
            <input 
              type="text" 
              value={formName}
              onChange={(e) => setFormName(e.target.value)}
              className={inputClass}
              placeholder="John Doe"
            />
          </div>

          <div>
            <label className={`block text-sm font-bold mb-1.5 ml-1 ${darkMode ? 'text-slate-300' : 'text-slate-700'}`}>{t('email', language)}</label>
            <input 
              type="email" 
              value={formEmail}
              onChange={(e) => setFormEmail(e.target.value)}
              className={inputClass}
              placeholder="you@example.com"
              required
            />
          </div>

          <div>
            <label className={`block text-sm font-bold mb-1.5 ml-1 ${darkMode ? 'text-slate-300' : 'text-slate-700'}`}>{t('password', language)}</label>
            <input 
              type="password" 
              value={formPassword}
              onChange={(e) => setFormPassword(e.target.value)}
              className={inputClass}
              placeholder="••••••••"
              required
            />
          </div>

          <button 
            type="submit"
            disabled={loading}
            className={`w-full relative group overflow-hidden py-3.5 sm:py-4 bg-gradient-to-r from-primary-600 to-purple-600 text-white rounded-2xl font-bold text-base sm:text-lg transition-all shadow-lg hover:shadow-primary-500/40 hover:-translate-y-1 mt-4 sm:mt-6 flex items-center justify-center gap-2 ${
              loading ? 'opacity-70 cursor-not-allowed' : ''
            }`}
          >
            <span className="absolute inset-0 w-full h-full bg-white/20 scale-x-0 group-hover:scale-x-100 transition-transform origin-left rounded-2xl"></span>
            <span className="relative z-10 flex items-center gap-2">
              {loading ? (
                <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
              ) : (
                isLogin ? <LogIn size={20} /> : <UserPlus size={20} />
              )}
              {loading ? 'Please wait...' : (isLogin ? t('signIn', language) : t('createAccount', language))}
            </span>
          </button>
        </form>

        <div className={`mt-6 sm:mt-8 text-center text-sm font-medium ${darkMode ? 'text-slate-400' : 'text-slate-500'}`}>
          {isLogin ? t('dontHaveAccount', language) : t('alreadyHaveAccount', language)}
          <button 
            onClick={() => { setIsLogin(!isLogin); setError(''); }}
            className="text-primary-600 font-bold hover:text-purple-600 transition-colors hover:underline decoration-2 underline-offset-4"
          >
            {isLogin ? t('signUp', language) : t('logIn', language)}
          </button>
        </div>
      </div>
    </div>
  );
}
